/** Playable prototype scene. Owns rendering and movement; UI supplies story events. No data or network writes. */
import * as T from './three.module.js';
export function createWorld(canvas,onInteract){
 const renderer=new T.WebGLRenderer({canvas,antialias:true,alpha:true});renderer.setPixelRatio(Math.min(devicePixelRatio,1.7));renderer.shadowMap.enabled=true;renderer.shadowMap.type=T.PCFSoftShadowMap;renderer.outputColorSpace=T.SRGBColorSpace;renderer.toneMapping=T.ACESFilmicToneMapping;
 let cameraGoal=new T.Vector3(12,13,20),lookGoal=new T.Vector3(0,0,0),lookNow=new T.Vector3(0,0,0);
 const scene=new T.Scene();scene.fog=new T.FogExp2(0x8d4b36,.024);const camera=new T.PerspectiveCamera(36,1,.1,160);camera.position.set(12,13,20);camera.lookAt(0,0,0);
 scene.add(new T.HemisphereLight(0xffd5bb,0x5b3027,2.5));const sun=new T.DirectionalLight(0xffd4a2,4);sun.position.set(-9,16,5);sun.castShadow=true;sun.shadow.mapSize.set(2048,2048);Object.assign(sun.shadow.camera,{left:-22,right:22,top:22,bottom:-22});sun.shadow.bias=-.001;scene.add(sun);
 const mat=(c,rough=.8,metal=0)=>new T.MeshStandardMaterial({color:c,roughness:rough,metalness:metal});const sand=mat(0xad6549),dark=mat(0x303a3c,.4,.6),white=mat(0xdbdbce,.7),orange=mat(0xcb6532),gold=mat(0xd5a768,.3,.5);
 function mesh(g,m,parent,pos=[0,0,0]){const x=new T.Mesh(g,m);x.position.set(...pos);x.castShadow=true;x.receiveShadow=true;parent.add(x);return x;}
 const box=(w,h,d,m,p,xyz)=>mesh(new T.BoxGeometry(w,h,d),m,p,xyz);const sphere=(radius,m,p,xyz)=>mesh(new T.SphereGeometry(radius,24,16),m,p,xyz);const cyl=(a,b,h,m,p,xyz)=>mesh(new T.CylinderGeometry(a,b,h,24),m,p,xyz);
 const ground=mesh(new T.PlaneGeometry(130,130,70,70),sand,scene);ground.rotation.x=-Math.PI/2;ground.position.y=-.04;const ar=ground.geometry.attributes.position;for(let i=0;i<ar.count;i++){const x=ar.getX(i),y=ar.getY(i);ar.setZ(i,Math.sin(x*.37)*Math.cos(y*.4)*.14)}ground.geometry.computeVertexNormals();ground.receiveShadow=true;
 let seed=37;const rand=()=>{seed=(seed*16807)%2147483647;return(seed-1)/2147483646};for(let i=0;i<120;i++){const x=(rand()-.5)*65,z=(rand()-.5)*50; if(Math.hypot(x,z)<4)continue;const rock=mesh(new T.DodecahedronGeometry(.08+rand()*.45,0),mat([0x955038,0x763e2f,0xbf7753][i%3]),scene,[x,.06,z]);rock.scale.set(1+rand(),.4+rand(),1);rock.rotation.set(rand(),rand()*6,rand());}
 const hill=mesh(new T.SphereGeometry(4.2,32,16),mat(0xab6043),scene,[1.8,-1.7,-5.5]);hill.scale.set(1.5,.8,.6);for(let i=0;i<14;i++){const m=mesh(new T.ConeGeometry(7+rand()*4,5+rand()*5,5),mat(0x88503e),scene,[-35+i*5,0,-28-rand()*12]);m.rotation.y=rand()*4;}
 const furnace=new T.Group();furnace.position.set(-2.1,0,.7);scene.add(furnace);cyl(1.08,1.23,.28,dark,furnace,[0,.15,0]);cyl(.88,.94,1.45,mat(0x6e6658,.9),furnace,[0,.95,0]);cyl(.94,1,.14,dark,furnace,[0,.5,0]);cyl(.92,.92,.18,dark,furnace,[0,1.5,0]);cyl(.33,.5,1.1,dark,furnace,[0,2.06,0]);cyl(.4,.4,.12,dark,furnace,[0,2.66,0]);const fireMat=new T.MeshStandardMaterial({color:0xff8c22,emissive:0xff4308,emissiveIntensity:3});box(.72,.62,.15,dark,furnace,[0,.85,.9]);box(.53,.43,.18,fireMat,furnace,[0,.84,1]);const glow=new T.PointLight(0xff6420,9,6);glow.position.set(0,1,1.3);furnace.add(glow);for(let i=-1;i<=1;i++)box(.05,.5,.1,dark,furnace,[i*.17,.84,1.13]);
 const astronaut=new T.Group();astronaut.position.set(.4,0,2);scene.add(astronaut);const torso=new T.Group();astronaut.add(torso);cyl(.3,.38,.68,white,torso,[0,.97,0]);box(.55,.48,.26,dark,torso,[0,1.02,-.3]);box(.28,.2,.06,orange,torso,[0,1.05,.33]);const head=sphere(.22,mat(0xc38d63),torso,[0,1.55,.035]);const hair=sphere(.235,mat(0x31251f),torso,[0,1.64,.015]);hair.scale.y=.6;const helmet=sphere(.36,new T.MeshPhysicalMaterial({color:0xb7d8de,transparent:true,opacity:.3,roughness:.1,metalness:.15,side:T.DoubleSide}),torso,[0,1.57,0]);cyl(.34,.34,.1,dark,torso,[0,1.34,0]);const arms=[],legs=[];for(const sign of [-1,1]){const arm=new T.Group();arm.position.set(sign*.42,1.2,0);torso.add(arm);cyl(.11,.12,.47,white,arm,[0,-.22,0]);sphere(.12,dark,arm,[0,-.49,0]);arms.push(arm);const leg=new T.Group();leg.position.set(sign*.19,.63,0);astronaut.add(leg);cyl(.14,.13,.48,white,leg,[0,-.2,0]);box(.27,.18,.42,dark,leg,[0,-.46,.08]);legs.push(leg)}
 const shovel=new T.Group();box(.06,1.15,.06,gold,shovel,[0,.2,0]);const blade=box(.3,.36,.08,dark,shovel,[0,-.45,0]);blade.rotation.x=-.3;shovel.position.set(.56,.67,.13);shovel.rotation.z=-.2;shovel.visible=false;astronaut.add(shovel);
 const digSpot=new T.Group();digSpot.position.set(3.2,0,-9.4);scene.add(digSpot);const ring=mesh(new T.RingGeometry(.7,.76,48),new T.MeshBasicMaterial({color:0xe1c58a,side:T.DoubleSide}),digSpot,[0,.07,0]);ring.rotation.x=-Math.PI/2;digSpot.visible=false;const chest=new T.Group();chest.position.set(3.2,-.6,-9.4);scene.add(chest);box(1,.5,.68,dark,chest,[0,.3,0]);box(1.05,.16,.72,gold,chest,[0,.62,0]);for(const x of [-.36,.36])box(.09,.57,.73,gold,chest,[x,.36,0]);box(.18,.2,.09,gold,chest,[0,.42,.4]);chest.visible=false;
 const ship=new T.Group();ship.position.set(6,0,-.7);scene.add(ship);cyl(.44,.65,2.4,white,ship,[0,2,0]);mesh(new T.ConeGeometry(.45,.9,32),dark,ship,[0,3.65,0]);cyl(.66,.66,.15,orange,ship,[0,1.1,0]);for(let i=0;i<3;i++){const fin=box(.15,1.4,.75,orange,ship,[Math.sin(i*2.094)*.6,.65,Math.cos(i*2.094)*.6]);fin.rotation.y=i*2.094;fin.rotation.z=.2;}sphere(.22,mat(0x172f3b,.1,.6),ship,[0,2.65,.43]);ship.visible=false;
 const sparks=new T.Group();scene.add(sparks);const particles=[];for(let i=0;i<35;i++){const p=mesh(new T.SphereGeometry(.025+rand()*.025,6,4),fireMat,sparks);p.visible=false;particles.push({p,v:new T.Vector3((rand()-.5)*7,2+rand()*5,(rand()-.5)*7)})}
 let target=astronaut.position.clone(),mode='idle',modeTime=0,elapsed=0,reduced=matchMedia('(prefers-reduced-motion: reduce)').matches,active=true;const keys=new Set();
 function resize(){const w=innerWidth,h=innerHeight;renderer.setSize(w,h);camera.aspect=w/h;cameraGoal.set(w<700?15:12,w<700?16:13,w<700?27:20);camera.position.copy(cameraGoal);camera.lookAt(0,0,0);camera.updateProjectionMatrix()}resize();window.addEventListener('resize',resize);
 const ray=new T.Raycaster(),pointer=new T.Vector2();canvas.addEventListener('pointerdown',e=>{if(!active||document.querySelector('dialog[open]'))return;pointer.set(e.clientX/innerWidth*2-1,-e.clientY/innerHeight*2+1);ray.setFromCamera(pointer,camera);const hits=ray.intersectObject(ground);if(hits[0]){target.copy(hits[0].point);target.y=0;target.x=T.MathUtils.clamp(target.x,-8,9);target.z=T.MathUtils.clamp(target.z,-12,7)}});
 window.addEventListener('keydown',e=>{if(!active||document.querySelector('dialog[open]')||/INPUT|TEXTAREA|SELECT/.test(e.target.tagName))return;if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','w','a','s','d'].includes(e.key)){e.preventDefault();keys.add(e.key)}if(e.key.toLowerCase()==='e')onInteract()});window.addEventListener('keyup',e=>keys.delete(e.key));window.addEventListener('blur',()=>keys.clear());
 function move(d){target.copy(astronaut.position);if(d==='up')target.z-=1.3;if(d==='down')target.z+=1.3;if(d==='left')target.x-=1.3;if(d==='right')target.x+=1.3;target.x=T.MathUtils.clamp(target.x,-8,9);target.z=T.MathUtils.clamp(target.z,-12,7)}
 const clock=new T.Clock();function tick(){requestAnimationFrame(tick);const dt=Math.min(clock.getDelta(),.05);elapsed+=dt;camera.position.lerp(cameraGoal,reduced?1:Math.min(1,dt*2));lookNow.lerp(lookGoal,reduced?1:Math.min(1,dt*2));camera.lookAt(lookNow);if(active){if(keys.size){target.copy(astronaut.position);if(keys.has('w')||keys.has('ArrowUp'))target.z-=1;if(keys.has('s')||keys.has('ArrowDown'))target.z+=1;if(keys.has('a')||keys.has('ArrowLeft'))target.x-=1;if(keys.has('d')||keys.has('ArrowRight'))target.x+=1;target.x=T.MathUtils.clamp(target.x,-8,9);target.z=T.MathUtils.clamp(target.z,-12,7)}const diff=target.clone().sub(astronaut.position);if(diff.length()>.06&&mode==='idle'){astronaut.position.add(diff.normalize().multiplyScalar(Math.min(3*dt,astronaut.position.distanceTo(target))));astronaut.rotation.y=Math.atan2(diff.x,diff.z);legs[0].rotation.x=Math.sin(elapsed*11)*.5;legs[1].rotation.x=-legs[0].rotation.x;arms[0].rotation.x=-legs[0].rotation.x;arms[1].rotation.x=legs[0].rotation.x}else{legs.forEach(l=>l.rotation.x=0);if(mode==='idle')arms.forEach(a=>a.rotation.x=0)}if(!reduced)glow.intensity=8+Math.sin(elapsed*9);if(mode!=='idle'){modeTime+=dt;if(mode==='forge'){arms[1].rotation.x=-.8+Math.sin(modeTime*12)*.6;}if(mode==='dig'){torso.rotation.x=.35+Math.sin(modeTime*8)*.12;arms.forEach(a=>a.rotation.x=-.8+Math.sin(modeTime*8)*.5)}if(mode==='smash'){if(modeTime<1){furnace.position.y=Math.sin(modeTime*Math.PI/2)*2;furnace.rotation.z=-modeTime*.3;arms.forEach(a=>a.rotation.x=-2)}else{furnace.position.y=Math.max(-.3,2-(modeTime-1)*8);furnace.rotation.z=-.3-(modeTime-1);if(modeTime>1.3){furnace.visible=false;particles.forEach(({p,v})=>{p.visible=true;const t=modeTime-1.3;p.position.set(-2.1+v.x*t,.2+v.y*t-4*t*t,.7+v.z*t)})}}}if(mode==='launch')ship.position.y+=dt*(modeTime*4);}}
 if(active)renderer.render(scene,camera)}tick();
 return{move,setActive(v){active=v;keys.clear();target.copy(astronaut.position)},reduce(v){reduced=v},go(kind){target.set(...(kind==='dig'?[6.8,0,-9.5]:[-1.2,0,1.6]));if(kind==='dig'){cameraGoal.set(innerWidth<700?15:11,innerWidth<700?16:12,-22);lookGoal.set(2,0,-8)}},action(kind){mode=kind;modeTime=0;if(kind==='launch'){ship.visible=true;ship.position.y=0;astronaut.visible=false;cameraGoal.set(12,13,20);lookGoal.set(3,3,0)}if(kind==='forge'||kind==='smash'){cameraGoal.set(innerWidth<700?15:12,innerWidth<700?16:13,innerWidth<700?27:20);lookGoal.set(0,0,0);astronaut.position.set(-.8,0,1.8);target.copy(astronaut.position)}if(kind==='dig'){astronaut.position.set(3.2,0,-8.9);target.copy(astronaut.position)}},finish(kind){mode='idle';astronaut.visible=true;torso.rotation.x=0;arms.forEach(a=>a.rotation.x=0);if(kind==='forge'){shovel.visible=true;digSpot.visible=true}if(kind==='dig'){chest.visible=true;chest.position.y=0;digSpot.visible=false;ship.visible=true;}},reset(){astronaut.visible=true;cameraGoal.set(innerWidth<700?15:12,innerWidth<700?16:13,innerWidth<700?27:20);lookGoal.set(0,0,0);furnace.visible=true;furnace.position.set(-2.1,0,.7);furnace.rotation.set(0,0,0);particles.forEach(x=>x.p.visible=false);shovel.visible=false;chest.visible=false;digSpot.visible=false;ship.visible=false;ship.position.y=0;astronaut.position.set(.4,0,2);target.copy(astronaut.position);mode='idle';torso.rotation.x=0},snapshot(){return {position:astronaut.position.toArray(),mode,shovel:shovel.visible,chest:chest.visible}}};
}
